import Foundation
import CRMCore

func runInboxExistingClientChecks(directory:URL) async throws -> Int {
    var count=0
    func expect(_ value:Bool,_ message:String) throws {guard value else {throw CheckFailure(message:message)};count += 1}
    let d=try JSONSerialization.jsonObject(with:Data(contentsOf:directory.appendingPathComponent("inbox-existing-client.json"))) as! [String:Any],fixture=FixtureInboxExistingClientPort(directory:directory)
    func context(_ x:[String:Int])->InboxConversationFilesContext {InboxConversationFilesContext(business:x["business"]!,conversation:x["conversation"]!,epoch:x["epoch"]!,revision:x["revision"]!)}
    let c=context(d["context"] as! [String:Int]),source=InboxExistingClientSource.decode(Data((d["source_json"] as! String).utf8),context:c)!,auth=fixture.grants[0].authorization(for:c)!,review=InboxExistingClientReview(source:source,authorization:auth,visit:1)
    for x in d["source_cases"] as! [[String:Any]] {let s=InboxExistingClientSource.decode(Data((x["response_json"] as! String).utf8),context:c);try expect((s != nil)==x["valid"] as! Bool,"Existing-client source \(x["name"]!)");try expect((s.map {InboxExistingClientReview(source:$0,authorization:auth,visit:1).valid} ?? false)==x["eligible"] as! Bool,"Null/invalid link qualified existing-only branch")}
    for x in d["grant_cases"] as! [[String:Any]] {let g=try JSONDecoder().decode(SyntheticInboxExistingClientGrant.self,from:JSONSerialization.data(withJSONObject:x["grant"]!));try expect((g.authorization(for:c) != nil)==x["valid"] as! Bool,"Two independent grants \(x["name"]!)")}
    var ledger=InboxExistingClientLedger();let a=ledger.begin(review)!,body=try JSONSerialization.jsonObject(with:a.preparedBody()) as! [String:Any];try expect(body.isEmpty && a.path=="/api/inbox/conversations/901/create-client/" && a.query.isEmpty && a.headers.isEmpty,"Existing branch invented name/contact/force/default/key/query")
    for x in d["receipt_cases"] as! [[String:Any]] {let receipt=InboxExistingClientReceipt.decode(Data((x["response_json"] as! String).utf8),attempt:a);try expect((receipt != nil)==x["valid"] as! Bool,"Exact existing-client wrapper/identity \(x["name"]!)");if let receipt {try expect(Mirror(reflecting:receipt).children.count==6,"Identity retained annotation/count/permission metadata")}}
    try expect(ledger.begin(review)==nil && !ledger.acknowledge(auth,record:ledger.visible(auth)!),"Pending duplicate/ack")
    ledger.complete(a,outcome:try await fixture.execute(a));let known=ledger.visible(auth)!;try expect(known.phase == .response && known.result?.id==701 && known.result?.phone=="  +77000000000  " && known.attempt.review.source==source,"Existing response changed source or normalized observed identity");ledger.complete(a,outcome:.unknown);try expect(ledger.visible(auth)==known && ledger.acknowledge(auth,record:known),"Late duplicate replaced known/history")
    let u=ledger.begin(review)!;ledger.complete(u,outcome:.unknown);let unknown=ledger.visible(auth)!,next=InboxConversationFilesContext(business:101,conversation:901,epoch:1001,revision:2),nextSource=InboxExistingClientSource.decode(Data((d["source_json"] as! String).utf8),context:next)!,na=fixture.grants[0].authorization(for:next)!
    ledger.complete(u,outcome:try await fixture.execute(u));try expect(ledger.visible(na)==unknown && !ledger.acknowledge(na,record:unknown) && ledger.begin(InboxExistingClientReview(source:nextSource,authorization:na,visit:2))==nil && unknown.attempt==u,"Matching existing Client response/conversation read/new epoch recovered unknown")
    let other=SyntheticInboxExistingClientGrant(business:101,conversation:901,actor:6001,clientsCreate:true,conversationsUpdate:true).authorization(for:next)!;try expect(ledger.visible(other)==nil && ledger.blocked(business:101,conversation:901) && !ledger.blocked(business:202,conversation:951),"Actor/owner barrier lost")
    for status in [201,202,204,400,403,409,500] {var l=InboxExistingClientLedger();let attempt=l.begin(review)!;if case .response(_,let data)=try await fixture.execute(attempt) {l.complete(attempt,outcome:.response(status:status,data:data))};try expect(l.visible(auth)?.phase == .unknown,"Non-plain200/new-client branch accepted")}
    var rejection=InboxExistingClientLedger();let rejected=rejection.begin(review)!;rejection.complete(rejected,outcome:.rejectedWithoutWrite);let record=rejection.visible(auth)!;try expect(record.phase == .rejected && rejection.acknowledge(auth,record:record) && rejection.records.count==1,"Known no-write refusal erased attempt")
    return count
}
